fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let bw: i32 = w / 8;
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, w / 2);
        host::display::state_set(2, h / 2);
        host::display::state_set(3, 3);
        host::display::state_set(4, -2);
        let mut i: i32 = 0;
        while i < 8 {
            host::display::state_set(20 + i, 1);
            i = i + 1;
        }
    }
    let mut bx: i32 = host::display::state_get(1);
    let mut by: i32 = host::display::state_get(2);
    let mut vx: i32 = host::display::state_get(3);
    let mut vy: i32 = host::display::state_get(4);
    let mut px: i32 = host::display::pointer_x() - 30;
    if px < 0 { px = 0; }
    if px > w - 60 { px = w - 60; }
    bx = bx + vx;
    by = by + vy;
    if bx < 0 { bx = 0; vx = 0 - vx; }
    if bx > w - 8 { bx = w - 8; vx = 0 - vx; }
    if by < 0 { by = 0; vy = 0 - vy; }
    if by > h - 24 && vy > 0 && bx + 8 > px && bx < px + 60 {
        by = h - 24;
        vy = 0 - vy;
    }
    if by > h {
        bx = w / 2;
        by = h / 2;
        vy = -2;
    }
    if by < 30 && by >= 14 {
        let hit: i32 = bx / bw;
        if hit >= 0 && hit < 8 && host::display::state_get(20 + hit) == 1 {
            host::display::state_set(20 + hit, 0);
            vy = 0 - vy;
        }
    }
    host::display::state_set(1, bx);
    host::display::state_set(2, by);
    host::display::state_set(3, vx);
    host::display::state_set(4, vy);
    host::display::clear(0x000000);
    let mut alive: i32 = 0;
    let mut i: i32 = 0;
    while i < 8 {
        if host::display::state_get(20 + i) == 1 {
            alive = alive + 1;
            host::display::fill_rect(i * bw + 1, 14, bw - 2, 14, 0xff6600);
        }
        i = i + 1;
    }
    if alive == 0 { host::display::state_set(0, 0); }
    host::display::fill_rect(px, h - 16, 60, 8, 0xffffff);
    host::display::fill_rect(bx, by, 8, 8, 0x00ffcc);
    host::display::draw_number(4, 0, alive, 0x808080, 1);
    host::display::present();
}
